SELECT opened_month, pct_frozen, stddev_balance FROM (SELECT DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, ROUND((100 * SUM(CASE WHEN status = 'FROZEN' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_frozen, ROUND(STDDEV(balance), 2) AS stddev_balance FROM accounts WHERE customer_id = 31 GROUP BY DATE_FORMAT(opened_date, 'yyyy-MM')) AS x WHERE pct_frozen < 72 ORDER BY opened_month;
